L000236	\section{Simulation methods}
L000237	
L000238	\begin{figure}[!ht]
L000239	    \centering
L000240	    \includegraphics[width=0.9\linewidth]{supp/cartoon.pdf}
L000241	    \caption{Initial and late time configuration of a typical system.}
L000242	    \label{fig: cartoon}
